"""Seeded synthetic screened population. Every row is fictional and generated by this file.

Distributions are documented in backend/data/DATA_CARD.md (generated by `python -m app.sim.run`)
and in the DISTRIBUTIONS dict below. They are assumptions chosen to make a plausible demo population.
They are not calibrated to any real population.
"""
from __future__ import annotations

import csv
from pathlib import Path

import numpy as np

REGIONS = ("AUH", "YDE")
REGION_NAMES = {"AUH": "Abu Dhabi", "YDE": "Yaounde"}
FIELDS = [
    "person_id", "region", "age", "age_band", "sex", "nationality_group", "preferred_language",
    "insurance_type", "phone_channel", "screening_sbp", "screening_dbp", "urgency", "actionable",
]
AGE_BANDS = ("18-29", "30-39", "40-49", "50-59", "60+")

# Placeholder thresholds copied from SPEC section 4.2 (the engine config is the real source and is pending sign-off).
SEVERE_SBP, SEVERE_DBP = 180, 110
RAISED_SBP, RAISED_DBP = 140, 90

DISTRIBUTIONS = {
    "AUH": {
        "age": "Normal(mean 38, sd 12), clipped to 18-85, rounded. Young skew for a mixed resident workforce.",
        "sex": {"male": 0.60, "female": 0.40},
        "nationality_group": {"Emirati": 0.20, "Expatriate Arab": 0.20, "South Asian": 0.40, "Other": 0.20},
        "preferred_language": {
            "Emirati": {"ar": 0.75, "en": 0.25}, "Expatriate Arab": {"ar": 0.60, "en": 0.40},
            "South Asian": {"ar": 0.02, "en": 0.98}, "Other": {"ar": 0.05, "en": 0.95}},
        "insurance_type": {
            "Emirati": {"thiqa": 0.80, "private": 0.20},
            "default": {"basic_enhanced": 0.45, "private": 0.35, "none": 0.20}},
        "phone_channel": {"app": 0.80, "sms": 0.12, "whatsapp": 0.08},
    },
    "YDE": {
        "age": "Normal(mean 36, sd 13), clipped to 18-85, rounded.",
        "sex": {"male": 0.45, "female": 0.55},
        "nationality_group": {"Cameroonian (single group)": 1.0},
        "preferred_language": {"fr": 0.92, "en": 0.08},
        "insurance_type": {"none": 0.85, "mutual_or_private": 0.10, "employer": 0.05},
        "phone_channel": {"sms": 0.60, "whatsapp": 0.40},
    },
}

# Blood pressure model (same form in both regions), documented in the data card:
#   sbp = 104 + 0.50 * (age - 18) + 3 * male + Normal(0, 13) + raised_extra
#   raised_extra = 0 for 85 percent of people, Normal(25, 12) for the other 15 percent (a raised subgroup)
#   dbp = 74 + 0.55 * (sbp - expected_sbp) + 0.10 * (age - 40) + Normal(0, 6.5)
# Values are rounded to whole mmHg and clipped to 80-240 (systolic) and 45-140 (diastolic).
BP_MODEL = {
    "sbp_base": 104.0, "sbp_per_year": 0.50, "sbp_male": 3.0, "sbp_noise_sd": 13.0,
    "raised_share": 0.15, "raised_mean": 25.0, "raised_sd": 12.0,
    "dbp_base": 74.0, "dbp_per_sbp": 0.55, "dbp_per_year": 0.10, "dbp_noise_sd": 6.5,
}


def age_band(age: int) -> str:
    return "18-29" if age < 30 else "30-39" if age < 40 else "40-49" if age < 50 else "50-59" if age < 60 else "60+"


def _choice(rng, options: dict, n: int):
    keys = list(options)
    return rng.choice(keys, size=n, p=[options[k] for k in keys])


def generate_region(region: str, n: int, seed: int) -> list[dict]:
    """Return n synthetic people for one region. Same seed gives identical rows."""
    rng = np.random.default_rng([seed, REGIONS.index(region)])
    d = DISTRIBUTIONS[region]
    mean, sd = (38, 12) if region == "AUH" else (36, 13)
    age = np.clip(np.rint(rng.normal(mean, sd, n)), 18, 85).astype(int)
    sex = _choice(rng, d["sex"], n)
    nat = _choice(rng, d["nationality_group"], n)
    channel = _choice(rng, d["phone_channel"], n)

    lang = np.empty(n, dtype=object)
    ins = np.empty(n, dtype=object)
    u_lang, u_ins = rng.random(n), rng.random(n)
    for i in range(n):
        lp = d["preferred_language"]
        lp = lp[nat[i]] if nat[i] in lp else lp
        lang[i] = _pick(lp, u_lang[i])
        ip = d["insurance_type"]
        ip = ip.get(nat[i], ip["default"]) if "default" in ip else ip
        ins[i] = _pick(ip, u_ins[i])

    m = BP_MODEL
    male = (sex == "male").astype(float)
    expected = m["sbp_base"] + m["sbp_per_year"] * (age - 18) + m["sbp_male"] * male
    raised = rng.random(n) < m["raised_share"]
    sbp = expected + rng.normal(0, m["sbp_noise_sd"], n) + np.where(raised, rng.normal(m["raised_mean"], m["raised_sd"], n), 0.0)
    dbp = m["dbp_base"] + m["dbp_per_sbp"] * (sbp - expected) + m["dbp_per_year"] * (age - 40) + rng.normal(0, m["dbp_noise_sd"], n)
    sbp = np.clip(np.rint(sbp), 80, 240).astype(int)
    dbp = np.clip(np.rint(dbp), 45, 140).astype(int)

    rows = []
    for i in range(n):
        urgency = urgency_of(int(sbp[i]), int(dbp[i]))
        rows.append({
            "person_id": f"{region}-{i + 1:05d}", "region": region, "age": int(age[i]), "age_band": age_band(int(age[i])),
            "sex": str(sex[i]), "nationality_group": str(nat[i]), "preferred_language": str(lang[i]),
            "insurance_type": str(ins[i]), "phone_channel": str(channel[i]),
            "screening_sbp": int(sbp[i]), "screening_dbp": int(dbp[i]), "urgency": urgency,
            "actionable": urgency != "NOT_ACTIONABLE",
        })
    return rows


def _pick(probs: dict, u: float) -> str:
    acc = 0.0
    for k, p in probs.items():
        acc += p
        if u < acc:
            return k
    return list(probs)[-1]


def urgency_of(sbp: int, dbp: int) -> str:
    if sbp >= SEVERE_SBP or dbp >= SEVERE_DBP:
        return "SEVERE"
    if sbp >= RAISED_SBP or dbp >= RAISED_DBP:
        return "RAISED"
    return "NOT_ACTIONABLE"


def write_csv(rows: list[dict], path: Path) -> None:
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=FIELDS, lineterminator="\n")
        w.writeheader()
        for r in rows:
            w.writerow({**r, "actionable": str(r["actionable"]).lower()})


def summary(rows: list[dict]) -> dict:
    n = len(rows)
    act = [r for r in rows if r["actionable"]]
    sev = [r for r in rows if r["urgency"] == "SEVERE"]
    return {
        "people": n, "actionable": len(act), "actionable_share": round(len(act) / n, 4),
        "severe": len(sev), "severe_share": round(len(sev) / n, 4),
        "mean_age": round(sum(r["age"] for r in rows) / n, 1),
        "mean_sbp": round(sum(r["screening_sbp"] for r in rows) / n, 1),
        "mean_dbp": round(sum(r["screening_dbp"] for r in rows) / n, 1),
    }
